import{_ as p,r as n,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const _=JSON.parse('{"title":"Настройки модели - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Настройки базы данных","slug":"настроики-базы-данных","link":"#настроики-базы-данных","children":[{"level":3,"title":"Определение класса модели","slug":"определение-класса-модели","link":"#определение-класса-модели","children":[]}]},{"level":2,"title":"Запись в модель настроек","slug":"запись-в-модель-настроек","link":"#запись-в-модель-настроек","children":[]},{"level":2,"title":"Чтение из модели настроек","slug":"чтение-из-модели-настроек","link":"#чтение-из-модели-настроек","children":[]},{"level":2,"title":"Интеграция с мультисайтом","slug":"интеграция-с-мультисаитом","link":"#интеграция-с-мультисаитом","children":[]}],"relativePath":"3.x/ru/extend/settings/model-settings.md","filePath":"3.x/ru/extend/settings/model-settings.md"}'),r={name:"3.x/ru/extend/settings/model-settings.md"};function u(k,s,d,g,m,h){const e=n("pre-heading"),t=n("post-heading");return o(),c("div",null,[a(e),s[0]||(s[0]=l("h1",null,"Настройки модели",-1)),a(t),s[1]||(s[1]=i(`<p>Настройки модели хранят значения в базе данных и могут быть переопределены через пользовательский интерфейс в панели управления.</p><h2 id="настроики-базы-данных"><a href="#настроики-базы-данных" class="header-anchor">#</a> Настройки базы данных</h2><p>Плагины могут использовать конфигурацию на основе базы данных, используя модели для хранения настроек в базе данных, наследуя базовый класс <code>System\\Models\\SettingModel</code>. Эта модель может использоваться непосредственно для создания формы настроек панели управления. Вам не нужно создавать таблицу базы данных и контроллер для создания форм настроек панели управления на основе модели настроек. Пример структуры директории модели настроек:</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── demo
|           ├── models
|           |   ├── usersetting  <em>← Директория конфигурации</em>
|           |   |   └── fields.yaml  <em>← Поля формы</em>
|           |   └── <code>UserSetting.php</code>  <em>← Класс модели</em>
|           └── Plugin.php</p>
</code></pre><p>Модели настроек могут быть зарегистрированы для отображения в <a href="./settings.html">области настроек панели управления</a>, но это не является обязательным — вы можете устанавливать и читать значения настроек как любую другую модель.</p><h3 id="определение-класса-модели"><a href="#определение-класса-модели" class="header-anchor">#</a> Определение класса модели</h3><p>Классы моделей настроек должны наследовать класс <code>System\\Models\\SettingModel</code> и, как любая другая модель, должны быть определены в поддиректории <strong>models</strong> директории плагина. Модель из следующего примера должна быть определена в файле <strong>plugins/acme/demo/models/UserSetting.php</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Demo<span class="token punctuation">\\</span>Models</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">UserSetting</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>SettingModel</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$settingsCode</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;acme_demo_settings&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$settingsFields</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;fields.yaml&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Свойство <code>$settingsCode</code> является обязательным для моделей настроек. Оно определяет уникальный ключ настроек, который используется для сохранения настроек в базе данных.</p><p>Свойство <code>$settingsFields</code> является обязательным, если вы собираетесь создать форму настроек панели управления на основе модели. Свойство указывает имя YAML-файла, содержащего определение полей формы. Поля формы описаны в <a href="./../forms/form-controller.html">статье о контроллере форм</a>. YAML-файл должен быть размещён в директории с именем, совпадающим с именем класса модели в нижнем регистре.</p><h2 id="запись-в-модель-настроек"><a href="#запись-в-модель-настроек" class="header-anchor">#</a> Запись в модель настроек</h2><p>Модель настроек имеет статический метод <code>set</code>, который позволяет сохранять отдельные или множественные значения. Вы также можете использовать стандартные возможности модели для установки свойств модели и сохранения модели.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">Acme<span class="token punctuation">\\</span>Demo<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>UserSetting</span><span class="token punctuation">;</span>

<span class="token comment">// Set a single value</span>
<span class="token class-name static-context">UserSetting</span><span class="token operator">::</span><span class="token function">set</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;api_key&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;ABCD&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Set an array of values</span>
<span class="token class-name static-context">UserSetting</span><span class="token operator">::</span><span class="token function">set</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;api_key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;ABCD&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Set object values</span>
<span class="token variable">$settings</span> <span class="token operator">=</span> <span class="token class-name static-context">UserSetting</span><span class="token operator">::</span><span class="token function">instance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$settings</span><span class="token operator">-&gt;</span><span class="token property">api_key</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;ABCD&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$settings</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="чтение-из-модели-настроек"><a href="#чтение-из-модели-настроек" class="header-anchor">#</a> Чтение из модели настроек</h2><p>Модель настроек имеет статический метод <code>get</code>, который позволяет загружать отдельные свойства. Также, когда вы создаёте экземпляр модели с помощью метода <code>instance</code>, он загружает свойства из базы данных, и вы можете обращаться к ним напрямую.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Outputs: ABCD</span>
<span class="token keyword">echo</span> <span class="token class-name static-context">UserSetting</span><span class="token operator">::</span><span class="token function">instance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token property">api_key</span><span class="token punctuation">;</span>

<span class="token comment">// Get a single value</span>
<span class="token keyword">echo</span> <span class="token class-name static-context">UserSetting</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;api_key&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Get a value and return a default value if it doesn&#39;t exist</span>
<span class="token keyword">echo</span> <span class="token class-name static-context">UserSetting</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_activated&#39;</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="интеграция-с-мультисаитом"><a href="#интеграция-с-мультисаитом" class="header-anchor">#</a> Интеграция с мультисайтом</h2><p>Модели настроек могут предоставлять различные значения конфигурации для каждого сайта, определённого <a href="./../../cms/resources/multisite.html">конфигурацией мультисайта</a>. Для включения мультисайта добавьте <a href="./../database/traits.html">трейт</a> <code>October\\Rain\\Database\\Traits\\Multisite</code> в модель и определите свойство <code>$propagatable</code>, которое может указывать поля, распространяющиеся на все сайты.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Demo<span class="token punctuation">\\</span>Models</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">UserSetting</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>SettingModel</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Multisite</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$settingsCode</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;acme_demo_settings&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$settingsFields</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;fields.yaml&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$propagatable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div>`,19))])}const y=p(r,[["render",u]]);export{_ as __pageData,y as default};
